@'
import json, re
from pathlib import Path
root=Path(r"D:\Project\MIAGuard")
files=[
"AGENTS.md","docs/README.md","docs/PROJECT_STATUS_ZH.md","docs/EXPERIMENT_INDEX_ZH.md",
"docs/DEFENSE_DEVELOPMENT_EXPERIMENT_RECOMMENDATIONS_ZH.md",
"docs/DEFENSE_PROGRESS_ZH.md","docs/DEFENSE_EXPERIMENT_PROTOCOL_ZH.md",
"docs/superpowers/specs/2026-10-22-defense-framework-design.md",
"docs/superpowers/plans/2026-10-22-defense-framework-implementation.md"]
errors=[]
links=0
for rel in files:
    p=root/rel
    s=p.read_text(encoding="utf-8")
    if len(re.findall(r"^\x60\x60\x60",s,re.M))%2:
        errors.append(rel+": unbalanced fences")
    for target in re.findall(r"\]\(([^)]+)\)",s):
        if target.startswith(("https://","http://","#")): continue
        links+=1
        if not (p.parent/target.split("#")[0]).resolve().exists():
            errors.append(rel+": missing "+target)
new=files[-4:]
for rel in new:
    s=(root/rel).read_text(encoding="utf-8")
    if re.search(r"\b(TODO|TBD|FIXME)\b",s): errors.append(rel+": placeholder")
plan=(root/files[-1]).read_text(encoding="utf-8")
ledger=(root/"docs/DEFENSE_PROGRESS_ZH.md").read_text(encoding="utf-8")
tasks=re.findall(r"^### (T\d{2}) ",plan,re.M)
expected=[f"T{i:02d}" for i in range(1,19)]
if tasks!=expected: errors.append("task headings mismatch")
for task in expected:
    if len(re.findall(r"^\| "+task+r" \|",ledger,re.M))!=1: errors.append(task+": ledger mismatch")
    if not re.search(r"^\| "+task+r" \|.*NOT_STARTED",ledger,re.M): errors.append(task+": initial status mismatch")
if "- [x]" in plan.lower(): errors.append("unexpected completed implementation checkbox")
for gate in ["G0","G1","G2","G3","G4"]:
    if gate not in plan or gate not in ledger: errors.append(gate+": missing")
result={"scope":"planning documents only","files_checked":len(files),"local_links_checked":links,"tasks":len(tasks),
"unchecked_steps":len(re.findall(r"^- \[ \]",plan,re.M)),"errors":errors,
"business_tests_run":False,"experiments_started":False}
print(json.dumps(result,ensure_ascii=False,indent=2))
if errors: raise SystemExit(1)
'@ | & 'D:\ProgramData\Anaconda3\envs\MIAGuard\python.exe' -
